#pragma once

#include <chrono>
#include <thread>

// java.util.concurrent.TimeUnit 的最小桩实现。
// Java 中 TimeUnit 是枚举，这里用「类 + 静态常量实例」模拟，
// 提供 NANOSECONDS / MICROSECONDS / MILLISECONDS / SECONDS 四个常用单位，
// 内部统一以「每单位纳秒数」作为换算基准。
class TimeUnit {
public:
    // 静态实例（C++17 inline 变量，定义在类外、仍在头文件中，header-only）
    static const TimeUnit NANOSECONDS;
    static const TimeUnit MICROSECONDS;
    static const TimeUnit MILLISECONDS;
    static const TimeUnit SECONDS;

    // 将以本单位的 d 换算为纳秒
    long toNanos(long d) const { return d * nanos_; }
    // 将以本单位的 d 换算为微秒
    long toMicros(long d) const { return d * nanos_ / 1000L; }
    // 将以本单位的 d 换算为毫秒
    long toMillis(long d) const { return d * nanos_ / 1000000L; }
    // 将以本单位的 d 换算为秒
    long toSeconds(long d) const { return d * nanos_ / 1000000000L; }

    // 将以 sourceUnit 为单位的 sourceDuration 换算为本单位
    // 与 Java 语义一致：MILLISECONDS.convert(1500, NANOSECONDS) == 0
    long convert(long sourceDuration, TimeUnit sourceUnit) const {
        return sourceUnit.nanos_ * sourceDuration / nanos_;
    }

    // 以本单位的 timeout 时长阻塞当前线程（Thread.sleep 语义）
    void sleep(long timeout) const {
        if (timeout > 0)
            std::this_thread::sleep_for(std::chrono::nanoseconds(toNanos(timeout)));
    }

private:
    explicit TimeUnit(long nanos) : nanos_(nanos) {}
    long nanos_;  // 每单位对应的纳秒数
};

// 静态实例的类外 inline 定义（C++17，保证 header-only 且无多重定义）
inline const TimeUnit TimeUnit::NANOSECONDS{1L};
inline const TimeUnit TimeUnit::MICROSECONDS{1000L};
inline const TimeUnit TimeUnit::MILLISECONDS{1000000L};
inline const TimeUnit TimeUnit::SECONDS{1000000000L};
